function validate([board]) {
  if (!Array.isArray(board) || board.length !== 2 || board.some(row => !Array.isArray(row) || row.length !== 3)) return 'board must have 2 rows of 3 cells.';
  const values = board.flat();
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 5)) return 'Every cell holds a whole number from 0 to 5.';
  if (new Set(values).size !== 6) return 'The values 0 to 5 must each appear once.';
  return null;
}

