function slidingPuzzle(board) {
  const target = '123450';
  const start = board.flat().join('');
  const neighbors = [[1, 3], [0, 2, 4], [1, 5], [0, 4], [1, 3, 5], [2, 4]];
  const seen = new Set([start]);
  let queue = [start];
  let moves = 0;

  while (queue.length > 0) {
    const next = [];
    for (const state of queue) {
      if (state === target) {
        return moves;
      }
      const zero = state.indexOf('0');
      for (const swap of neighbors[zero]) {
        const cells = state.split('');
        [cells[zero], cells[swap]] = [cells[swap], cells[zero]];
        const child = cells.join('');
        if (!seen.has(child)) {
          seen.add(child);
          next.push(child);
        }
      }
    }
    queue = next;
    moves++;
  }
  return -1;
}

