function slidingPuzzle(board) {
  // Relax distances over all 720 boards until nothing changes (Bellman-Ford style).
  const all = [];
  const permute = (prefix, rest) => {
    if (rest.length === 0) { all.push(prefix); return; }
    rest.forEach((v, i) => permute(prefix.concat(v), rest.slice(0, i).concat(rest.slice(i + 1))));
  };
  permute([], [0, 1, 2, 3, 4, 5]);
  const keyOf = cells => cells.join(',');
  const dist = new Map(all.map(cells => [keyOf(cells), Infinity]));
  dist.set('1,2,3,4,5,0', 0);
  const moves = cells => {
    const at = cells.indexOf(0), row = Math.floor(at / 3), col = at % 3, out = [];
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const r = row + dr, c = col + dc;
      if (r < 0 || r > 1 || c < 0 || c > 2) continue;
      const copy = cells.slice();
      copy[at] = copy[r * 3 + c];
      copy[r * 3 + c] = 0;
      out.push(keyOf(copy));
    }
    return out;
  };
  let changed = true;
  while (changed) {
    changed = false;
    for (const cells of all) {
      const key = keyOf(cells);
      for (const other of moves(cells)) {
        if (dist.get(other) + 1 < dist.get(key)) { dist.set(key, dist.get(other) + 1); changed = true; }
      }
    }
  }
  const answer = dist.get(keyOf([...board[0], ...board[1]]));
  return answer === Infinity ? -1 : answer;
}

